const link=(url,text)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${text} ↗</a>`;
const sources=(...items)=>`<div class="sources">Read further: ${items.map(([u,t])=>link(u,t)).join(' ')}</div>`;
const gebco=['https://www.gebco.net/data-products/gridded-bathymetry-data','GEBCO data & documentation'];
const emodnet=['https://emodnet.ec.europa.eu/en/bathymetry','EMODnet Bathymetry'];
const noaa=['https://www.ncei.noaa.gov/products/bathymetry','NOAA NCEI'];
const mb=['https://www.mbari.org/technology/mb-system/','MB-System'];
const box=(title,text,warm=false)=>`<div class="callout ${warm?'warm':''}"><h3>${title}</h3><p>${text}</p></div>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const figure=(interactive=false)=>`<div class="figure"><div class="figure-top"><span>SPECIMEN 001 / SYNTHETIC SEAFLOOR</span><span>PLAN VIEW · 10 × 6 KM</span></div><div class="canvas-wrap"><canvas id="terrain" role="img" aria-label="Synthetic depth grid showing a broad ridge and a small mound; this is not a real place or survey."></canvas></div>${interactive?'<div class="controls"><label for="resolution">Grid cell size</label><input type="range" id="resolution" min="0" max="3" value="0" step="1"><output id="res-value" for="resolution">50 m</output></div>':''}<div class="figure-bottom"><span>Illustrative model · not surveyed data</span><span class="legend">DEEP <i class="ramp"></i> SHALLOW</span></div></div>`;
const chapters=[
{slug:'intro',nav:'Read the seafloor',title:'A whole landscape.<br>Hidden in plain sight.',intro:'Bathymetry is the measurement and mapping of underwater depth. Think topography, with water in the way. Your first task is to understand what a map actually knows.',body:()=>figure()+`<div class="grid"><div class="card"><span class="eyebrow">01 / MEASURE</span><h3>Depth becomes data</h3><p>A sounding pairs a location with a depth. Many soundings can describe a submerged landscape.</p></div><div class="card"><span class="eyebrow">02 / MODEL</span><h3>Data becomes a surface</h3><p>A grid divides space into cells. Each cell holds a value, measured or estimated from surrounding evidence.</p></div><div class="card"><span class="eyebrow">03 / INTERPRET</span><h3>A surface raises questions</h3><p>Ridges, channels and shelves tell a story. A map alone cannot establish what made a feature or how old it is.</p></div></div>`+box('Start with the question, then choose the data.','“Where is the continental shelf?” and “Is that a submerged wall?” demand very different coverage, resolution and supporting evidence.')+`<h2>Your route through the field</h2><p>Learn the instruments, compare available datasets, inspect their limitations, and follow a small grid from download to visualization. Finish with an evidence checklist for your own exploration.</p>`+sources(noaa,gebco)},
{slug:'measurements',nav:'How depth is measured',title:'Not all depth data<br>comes from a sonar.',intro:'The way a measurement is collected determines what it can reveal—and what it can get wrong.',body:()=>table(['Method','What you get','Where it breaks down'],[
['Single-beam sonar','Depth samples along a vessel’s path.','Wide gaps between tracks leave the intervening terrain unmeasured.'],['Multibeam sonar','A fan of soundings covering a swath of seabed; often accompanying backscatter intensity.','Footprint grows with depth. Sound speed, vessel motion and positioning errors need correction.'],['Bathymetric lidar','Laser-derived depths in relatively clear, shallow water.','Water clarity, surface conditions and bottom reflectivity limit penetration.'],['Optical satellite bathymetry','Shallow-water depth estimates inferred from reflected light.','Turbidity, bottom type and calibration affect estimates; it does not image the deep seafloor.'],['Satellite altimetry + gravity','Broad deep-ocean terrain inferred from sea-surface gravity signatures, constrained by soundings.','Indirect estimation; cannot resolve small archaeological structures.']])+box('Backscatter is not depth.','Backscatter records acoustic return strength. It can help distinguish seabed textures, but brightness also depends on geometry and acquisition. Side-scan imagery shows texture and shadows; a conventional image is not an elevation grid.')+`<h2>Why raw sonar is a later step</h2><p>Raw measurements need navigation, sound-speed, motion and water-level corrections, outlier review and uncertainty assessment before gridding. Begin with a processed terrain model, then revisit the acquisition pipeline when the grid stops answering your questions.</p>`+sources(noaa,mb)},
{slug:'resolution',nav:'Resolution & uncertainty',title:'More pixels.<br>Not more evidence.',intro:'Cell spacing is a property of the grid. Effective resolution and accuracy depend on the observations and processing behind it.',body:()=>figure(true)+`<p id="resolution-note" aria-live="polite">At 50 m spacing, this synthetic model retains its small mound. Increase the cell size and watch that detail disappear.</p>`+box('Try it: move from 50 m to 1,000 m.','This demonstration averages an invented surface into larger cells. The small feature becomes less distinct. Interpolating a coarse grid back to 50 m would add pixels, not recover the missing observations.')+table(['Concept','What to ask'],[['Cell spacing','How far apart are the grid values? Angular spacing changes in east–west ground distance with latitude.'],['Effective resolution','What size feature is actually supported by the footprint, sample density and processing?'],['Accuracy & uncertainty','How close are values to reality, and how uncertain are individual locations or depths?'],['Coverage & provenance','Was this cell surveyed, interpolated or inferred? What survey and date contributed?'],['Datum & units','What horizontal coordinate system and vertical reference were used? Is depth positive down or elevation negative below sea level?']])+`<div class="check"><h3>Quick check</h3><p>You resample a 500 m grid to 5 m cells. What changed?</p><div class="answers"><button data-answer="wrong">It can now reveal 5 m objects</button><button data-answer="right">The sampling grid, not the underlying evidence</button></div><p class="feedback" id="feedback" aria-live="polite"></p></div>`+sources(gebco,emodnet)},
{slug:'datasets',nav:'Find your first dataset',title:'An atlas, a regional model,<br>or an individual survey?',intro:'Start broad to find context, then seek local observations. Coverage is not the same as a guarantee of fine detail.',body:()=>table(['Source','Best starting use','Limit to remember'],[
[link(...gebco),'Global context. The GEBCO 2026 grid has 15 arc-second spacing (about 463 m north–south). Download a small subset plus its Type Identifier grid.','Source quality varies. TID indicates source type, not a per-cell accuracy guarantee.'],
[link(...emodnet),'European seas, including the Mediterranean. Explore the regional DTM, source references and local higher-resolution products.','A merged surface can combine different surveys and gap-filling. Check the specific product’s metadata and access terms.'],
[link(...noaa),'Discover archived multibeam, single-beam and gridded products using the bathymetric data viewer.','Survey coverage is uneven; raw files require more processing than ready-made DEMs.']])+box('A useful first region: the waters around Malta.','Choose a small offshore box, for example 14.0–14.8° E and 35.5–36.2° N. Use it to learn regional terrain and compare source coverage. This is a learning area, not an Atlantis candidate.')+`<h2>Before downloading</h2><ul><li>Record the product name, release, source URL, access date and area bounds.</li><li>Read the license, attribution requirements, datum, units and NoData definition.</li><li>Check survey provenance and whether higher-resolution observations exist.</li><li>Download the smallest useful subset, together with its documentation and quality layers.</li></ul>`+sources(gebco,emodnet,noaa)},
{slug:'formats',nav:'Formats & storage',title:'Keep the numbers.<br>Keep their history.',intro:'A colored map is a view of your data. Your working copy should retain numeric depths, coordinates, missing-data values and provenance.',body:()=>table(['Format / service','Role','Practical distinction'],[['GeoTIFF / COG','Georeferenced raster; COG adds a layout suitable for partial web reads.','Keep numeric values. An RGB picture in a GeoTIFF is still only a picture.'],['NetCDF','Scientific arrays with coordinates and metadata; common in global terrain products.','Inspect variable names, dimensions, units, missing values and coordinate conventions.'],['BAG','Bathymetric grid format supporting elevation and uncertainty.','Useful survey deliverable; inspect which layers and extensions are present.'],['XYZ / CSV','A simple table of coordinates and depths.','Units, CRS and datum are easy to lose. Preserve an accompanying metadata file.'],['WMS / map tiles','Rendered imagery for browsing.','Do not treat displayed colors as the original depth values.'],['Raw sonar formats','Instrument or exchange files for reprocessing.','Much larger and more complex than a final grid. Preserve associated calibration and navigation.']])+`<h2>A small, reproducible workspace</h2><pre>malta-study/
  raw/          # unchanged downloads + documentation
  processed/    # clipped or reprojected numeric grids
  outputs/      # hillshades, contours, figures
  scripts/      # repeatable processing steps
  manifest.json # sources, versions, units, CRS, datum, license</pre><p>Keep raw downloads immutable. Store checksums and processing parameters in the manifest. Use Git for scripts and small metadata; keep large rasters in file or object storage with backups. Create reduced-resolution overviews for fast display.</p>`+box('Storage grows with area and detail.','A 10,000 × 10,000 grid of 32-bit values occupies about 400 MB before compression, metadata, overviews or extra layers. Several temporary arrays can multiply memory use. A regional subset is an easier first project than a whole-ocean download.')+sources(['https://gdal.org/en/stable/drivers/raster/cog.html','GDAL: Cloud Optimized GeoTIFF'],gebco)},
{slug:'processing',nav:'Your first processing workflow',title:'One small grid.<br>A complete workflow.',intro:'Use QGIS for the first pass. The goal is to understand every transformation before automating it.',body:()=>`<ol><li><strong>Acquire.</strong> Download a numeric GeoTIFF subset from GEBCO and its matching TID grid. Save the documentation and release details.</li><li><strong>Inspect.</strong> Open the raster in QGIS. Check CRS, extent, pixel size, band values and NoData. Verify depth sign and vertical reference in the source documentation.</li><li><strong>Style.</strong> Apply a single-band pseudocolor depth ramp. Keep the color range fixed when comparing grids. Make missing cells transparent.</li><li><strong>Clip and project.</strong> Retain the original. For local distance and slope calculations around Malta, make a working copy in an appropriate metric CRS, such as WGS 84 / UTM zone 33N (EPSG:32633). Horizontal reprojection does not convert the vertical datum.</li><li><strong>Resample deliberately.</strong> Use a sensible output spacing close to the source information content. Bilinear interpolation can suit continuous terrain; use nearest-neighbour for categorical TID codes.</li><li><strong>Derive views.</strong> Generate hillshade, contours and slope with horizontal and vertical units accounted for. Compare more than one illumination direction.</li><li><strong>Validate.</strong> Inspect seams, spikes, missing cells and source changes. Compare against original values and survey provenance.</li><li><strong>Export.</strong> Save the numeric working raster, view settings and processing steps. Export a labeled figure with source, scale, units and any vertical exaggeration.</li></ol>`+box('A five-minute observation exercise','Find a broad shelf edge or channel. Describe it without assigning an origin: “a slope break at this location” is an observation; “a harbor wall” is a hypothesis. Check whether the shape follows a survey boundary.')+sources(['https://docs.qgis.org/latest/en/docs/training_manual/','QGIS training manual'],['https://gdal.org/en/stable/programs/index.html','GDAL tools'],mb)},
{slug:'communities',nav:'People & communities',title:'Learn alongside the<br>people making the maps.',intro:'Use mapping communities for data and methods, GIS communities for practical tooling, and archaeologists for cultural interpretation.',body:()=>[
['https://seabed2030.org/','Seabed 2030','Global seafloor mapping initiative. Find regional centers, mapping efforts and opportunities to contribute.'],
['https://www.gebco.net/','GEBCO','A starting point for training, the bathymetry Cook Book, symposia and the ocean mapping community.'],
['https://www.mbari.org/technology/mb-system/','MB-System community','Open-source sonar processing, documentation and user support. Useful when moving beyond finished grids.'],
['https://qgis.org/community/','QGIS community','User groups and support channels for raster workflows, projections and visualization.'],
['https://www.unesco.org/en/underwater-heritage','UNESCO underwater cultural heritage','Context for responsible study and preservation of submerged cultural sites.']
].map(([u,t,d])=>`<a class="resource" href="${u}" target="_blank" rel="noopener noreferrer"><strong>${t} ↗</strong><span>${d}</span></a>`).join('')+box('Ask a question someone can reproduce.','Share the dataset release, bounding box, CRS, cell size, relevant processing steps and a labeled screenshot. Ask “Does this line coincide with a survey seam?” before asking “Have I found a city?”')},
{slug:'exploration',nav:'From map to hypothesis',title:'Keep the ambition.<br>Make the evidence earn it.',intro:'An Atlantis-inspired search can motivate real learning. Bathymetry can identify candidate terrain; it cannot establish a lost civilization from geometry alone.',body:()=>`<h2>An evidence ladder for unusual features</h2><ol><li><strong>Describe the observation.</strong> Record coordinates, dimensions, depth and uncertainty. Avoid naming the feature by the explanation you hope is true.</li><li><strong>Challenge the map.</strong> Check source boundaries, trackline patterns, interpolation and processing artifacts. Change shading and inspect numeric profiles.</li><li><strong>Check scale.</strong> Is the feature supported by several independent observations, or mostly one or two cells?</li><li><strong>Seek independent evidence.</strong> Two products may reuse the same surveys. Trace their lineage before calling agreement independent confirmation.</li><li><strong>Compare explanations.</strong> Geology, sediment transport and acquisition artifacts can create regular-looking forms. Archaeological interpretation needs context, dating and appropriate expert review.</li></ol>`+box('Discovery and creation are separate projects.','If “creating an Atlantis” becomes a designed underwater world, synthetic terrain is a useful sandbox. Keep fictional reconstructions labeled and separate from measured observations.',true)+`<h2>The next build: a real-data viewer</h2><span class="badge">NEXT PHASE · NOT YET IMPLEMENTED</span><p>Once the tutorial is familiar, extend this playground around one small, attributed dataset. The first viewer should make uncertainty visible, not just make terrain beautiful.</p>`+table(['Step','What we would build'],[['1 · Load','Import a small numeric GeoTIFF; inspect bounds, CRS, units, datum and NoData.'],['2 · Explore','Depth colors, hillshade controls, contours, cursor depth and a distance–depth profile.'],['3 · Compare','Source / TID overlay and two datasets with a shared scale and documented lineage.'],['4 · Investigate','A notebook of candidate features with evidence, alternative explanations and reproducible exports.']])+box('Your first milestone','Complete the Malta subset workflow. Bring back one labeled map, its source details and one observation you can defend. That gives us a concrete dataset and question for the next iteration.')+sources(gebco,['https://www.unesco.org/en/underwater-heritage','Underwater heritage context'])}
];
let current=0;
function render(){const slug=location.hash.slice(1)||'intro';current=Math.max(0,chapters.findIndex(c=>c.slug===slug));const c=chapters[current];document.title=`${c.nav} — BathymetryPlayground`;document.getElementById('chapters').innerHTML=chapters.map((x,i)=>`<a href="#${x.slug}" class="${i===current?'active':''}" ${i===current?'aria-current="step"':''}><span class="num">${String(i+1).padStart(2,'0')}</span>${x.nav}</a>`).join('');document.getElementById('content').innerHTML=`<span class="eyebrow">CHAPTER ${String(current+1).padStart(2,'0')}</span><h1>${c.title}</h1><p class="lede">${c.intro}</p>${c.body()}`;document.getElementById('chapter-counter').textContent=`${String(current+1).padStart(2,'0')} / 08`;document.getElementById('progress-label').textContent=`Chapter ${current+1} of 8`;document.getElementById('progress').style.width=((current+1)/8*100)+'%';document.getElementById('previous').disabled=current===0;document.getElementById('next').textContent=current===7?'Back to introduction ↺':'Next chapter →';document.getElementById('footer-label').textContent=current===7?'You’ve reached the end of the guide':`Up next: ${chapters[current+1].nav}`;draw();const slider=document.getElementById('resolution');if(slider)slider.addEventListener('input',()=>{const m=[50,200,500,1000][+slider.value];document.getElementById('res-value').textContent=m.toLocaleString()+' m';document.getElementById('resolution-note').textContent=m===50?'At 50 m spacing, this synthetic model retains its small mound. Increase the cell size and watch that detail disappear.':`At ${m.toLocaleString()} m spacing, each displayed cell averages a larger area. Small features lose definition; the model has not become more accurate.`;draw()});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{document.getElementById('feedback').textContent=b.dataset.answer==='right'?'Correct. Resampling changes the grid; it does not create new observations.':'Not quite. Smaller output cells cannot reveal detail absent from the source measurements.'});}
function field(x,y){return -2800+1300*Math.exp(-Math.pow((x-.45-y*.3)*5,2))+1400*Math.exp(-((x-.24)**2+(y-.37)**2)/.0018)+190*Math.sin(x*12+y*4)}
function draw(){const canvas=document.getElementById('terrain');if(!canvas)return;const rect=canvas.getBoundingClientRect();const dpr=window.devicePixelRatio||1;canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const w=rect.width,h=rect.height;const cell=[50,200,500,1000][+(document.getElementById('resolution')?.value||0)];const nx=10000/cell,ny=6000/cell;const stops=[[16,40,72],[23,107,136],[112,211,187],[242,217,149]];for(let y=0;y<ny;y++){for(let x=0;x<nx;x++){let z=0;for(let a=0;a<4;a++)for(let b=0;b<4;b++)z+=field((x+(a+.5)/4)/nx,(y+(b+.5)/4)/ny);z/=16;const t=Math.max(0,Math.min(2.999,(z+3000)/2700*3)),i=Math.floor(t),f=t-i;ctx.fillStyle=`rgb(${stops[i].map((v,j)=>Math.round(v+(stops[i+1][j]-v)*f)).join(',')})`;ctx.fillRect(x*w/nx,y*h/ny,w/nx+.5,h/ny+.5)}}ctx.strokeStyle='rgba(205,235,240,.12)';ctx.lineWidth=1;for(let x=0;x<6;x++){ctx.beginPath();ctx.moveTo(x*w/5,0);ctx.lineTo(x*w/5,h);ctx.stroke()}for(let y=0;y<4;y++){ctx.beginPath();ctx.moveTo(0,y*h/3);ctx.lineTo(w,y*h/3);ctx.stroke()}ctx.fillStyle='#e8f7f5';ctx.font='12px monospace';ctx.fillText('N ↑',18,28);ctx.fillText('0',18,h-17);ctx.fillText('2 km',w*.2+18,h-17);ctx.fillRect(18,h-38,w*.2,2);}
document.getElementById('previous').onclick=()=>{if(current>0)location.hash=chapters[current-1].slug};document.getElementById('next').onclick=()=>location.hash=chapters[(current+1)%chapters.length].slug;window.addEventListener('hashchange',()=>{render();document.getElementById('lesson').focus({preventScroll:true});window.scrollTo(0,0)});window.addEventListener('resize',draw);render();
